CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, name VARCHAR(255) NOT NULL, sku VARCHAR(100), barcode_type VARCHAR(50), unit_id INT, brand_id INT, category_id INT, tax_id INT, type ENUM('single', 'variable', 'combo') DEFAULT 'single', enable_stock BOOLEAN DEFAULT TRUE, alert_quantity DECIMAL(15,4), purchase_price DECIMAL(15,4) DEFAULT 0, selling_price DECIMAL(15,4) DEFAULT 0, image VARCHAR(255), description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
